function jToDate(s){
  const target=S(s).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/-/g,'/');
  if(!/^\d{4}\/\d{2}\/\d{2}$/.test(target))return null;
  try{
    const fmt=new Intl.DateTimeFormat('en-CA-u-ca-persian',{year:'numeric',month:'2-digit',day:'2-digit'}),base=new Date();
    for(let offset=-740;offset<=740;offset++){
      const d=new Date(base.getFullYear(),base.getMonth(),base.getDate()+offset),parts=fmt.formatToParts(d),get=k=>parts.find(x=>x.type===k)?.value||'';
      if(`${get('year')}/${get('month')}/${get('day')}`===target)return d;
    }
  }catch(_){}
  return null;
}
function dateToJ(d){const p=new Intl.DateTimeFormat('en-US-u-ca-persian',{year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(d),g=t=>p.find(x=>x.type===t)?.value;return `${g('year')}/${g('month')}/${g('day')}`}
