// Exact share of one tip group; only the monthly total is rounded down (staffTipRoundMonthly). A share of a group saved while
// shares were rounded per group (shareRoundingStep) that is already settled keeps the entitlement recorded in the settlement.
function tipShareStaff(g){const ps=A(g.participants),r=ps.find(x=>x.personnelId===me.id),sum=ps.reduce((a,x)=>a+(N(x.weight)||1),0),raw=r&&sum?N(g.totalAmount)*(N(r.weight)||1)/sum:0;if(!(N(g.shareRoundingStep)>0))return raw;const key=g.id+':'+me.id,a=A(hr.payments).filter(p=>p&&p.tipSettlement===true&&!['void','ابطال‌شده','لغوشده'].includes(S(p.status))).flatMap(p=>A(p.tipAllocations)).find(x=>x.tipShareId===key&&x.entitlementToman!==undefined&&x.entitlementToman!==null);return a?N(a.entitlementToman):raw}
function staffTipRoundMonthly(v){const raw=hr?.settings?.tipShareRoundingStep,step=raw===''||raw===undefined||raw===null?5000:Math.max(0,N(raw));return step>0?Math.floor(N(v)/step+1e-9)*step:N(v)}
function tipSettledShareStaff(g){const share=tipShareStaff(g),total=N(g.totalAmount),settled=N(g.settledAmount),status=S(g.status);if(/پرداخت|تسویه/.test(status)||total>0&&settled>=total)return share;if(total>0&&settled>0)return share*Math.min(1,settled/total);return 0}
