function staffBevItems(){const all=A(pricing?.ingredients);return A(inventory?.settings?.beverageControl?.itemIds).map(id=>all.find(i=>i.id===id)).filter(Boolean)}
async function staffBevActor(){const fresh=await latest('hr'),p=A(fresh?.personnel).find(x=>x.id===me?.id);if(!p||p.status!=='فعال'||p.userAccess?.enabled!==true||p.userAccess?.permissions?.beverageControl!==true)throw new Error('دسترسی ثبت کنترل نوشابه برای حساب شما فعال نیست؛ با مدیر هماهنگ کنید.');return{type:'staff',personnelId:p.id,name:S(p.name)}}
function staffBevCfg(){const R=window.RayoBeverageControl;return{title:'ثبت اطلاعات کنترل مغایرت نوشابه',items:staffBevItems,people:()=>A(hr?.personnel).filter(p=>p.status==='فعال').map(p=>({id:p.id,name:p.name})),load:()=>latest('inventory'),onLoaded:d=>{inventory=d},save:async d=>(await RAYO_API_GATEWAY.saveModule('inventory',d))?.checked||null,onSaved:d=>{inventory=d;staffBevRefreshMine()},actor:staffBevActor,canEdit:(date,existing)=>existing&&date<R.addDays(R.today(),-1)?'اطلاعات این تاریخ قبلاً ثبت شده است؛ اصلاح تاریخ‌های قبل از دیروز فقط توسط مدیر انجام می‌شود.':'',toast:toastStaff}}
function staffBevMine(){const R=window.RayoBeverageControl,rows=[];for(const rec of R.records(inventory))for(const l of A(rec.lines)){const stages=[l.morningCountedBy?.personnelId===me.id?'صبح':'',l.nightCountedBy?.personnelId===me.id?'شب':''].filter(Boolean),legacy=!l.updatedBy&&rec.createdByPersonnelId===me.id;if(!stages.length&&l.updatedBy?.personnelId!==me.id&&!legacy)continue;rows.push({date:S(rec.date),name:l.itemNameSnapshot||l.ingredientId,stages:stages.join(' و ')||(legacy?'فرم کامل (قدیمی)':'ویرایش'),by:S(l.updatedBy?.name||rec.createdByName),at:S(l.updatedAt||rec.createdAt)})}
 rows.sort((a,b)=>b.date.localeCompare(a.date)||b.at.localeCompare(a.at));
 return `<div class="section-head"><h2>ثبت‌های من</h2></div><div class="table-wrap"><table class="data-table"><thead><tr><th>تاریخ</th><th>نوشیدنی</th><th>مرحله ثبت‌شده توسط شما</th><th>آخرین ویرایش</th></tr></thead><tbody>${rows.slice(0,60).map(r=>`<tr><td>${E(r.date)}</td><td>${E(r.name)}</td><td>${E(r.stages)}</td><td>${E(r.by)}${r.at?` — ${E(R.atText(r.at))}`:''}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">هنوز ثبتی ندارید.</td></tr>'}</tbody></table></div>`}
function staffBevRefreshMine(){const c=document.getElementById('stBevMine');if(c){c.innerHTML=staffBevMine();staffEnhanceTables()}}
function staffBeverageView(){if(!permissions().beverageControl)return '<div class="card empty">دسترسی کنترل روزانه فروش نوشابه فعال نیست.</div>';if(!window.RayoBeverageControl)return '<div class="card empty" role="alert">ماژول کنترل نوشابه بارگذاری نشد؛ صفحه را بروزرسانی کنید.</div>';if(!inventory||!pricing)return '<div class="card empty" role="alert">اطلاعات انبار یا کاتالوگ بارگذاری نشد؛ صفحه را بروزرسانی کنید.</div>';
 const head=`<div class="page-head"><div><h1>${STAFF_BEV_TITLE}</h1><p>ابتدا تاریخ و سپس نوشیدنی را انتخاب کنید و اعداد همان نوشیدنی را وارد کنید. خانه خالی یعنی «وارد نشده»؛ اگر کالایی نیست «۰» بنویسید. نام شما به‌عنوان شمارنده همان مرحله ثبت می‌شود.</p></div></div>`;
 if(!staffBevItems().length)return head+'<div class="card empty">مدیر هنوز اقلام نوشیدنی کنترل روزانه را تعیین نکرده است.</div>';
 return head+window.RayoBeverageControl.form.html(staffBevCfg())+`<div class="card" id="stBevMine">${staffBevMine()}</div>`}
// Read-only staff tables: click a header to sort, long lists show 20 rows with "show more".
// Tables with inputs (e.g. inventory count) are skipped so their own search/filter keeps working.
const STAFF_TABLE_PAGE=20;
function staffCellValue(td){const raw=DG(td?.textContent).replace(/[٬,]/g,'').trim(),d=raw.match(/^(\d{4})\/(\d{1,2})\/(\d{1,2})/);if(d)return{n:true,v:+d[1]*10000+(+d[2])*100+(+d[3])};const m=raw.match(/^[-−]?\d+(\.\d+)?(?=\s|$|تومان|ریال)/);return m?{n:true,v:parseFloat(m[0].replace('−','-'))}:{n:false,v:raw}}
function staffEnhanceTables(){document.querySelectorAll('#staffView table.data-table').forEach(t=>{const body=t.tBodies[0];if(t.dataset.stEnhanced||!body||t.querySelector('tbody input,tbody select,tbody textarea'))return;t.dataset.stEnhanced='1';const st={limit:STAFF_TABLE_PAGE,col:-1,dir:1},rowsOf=()=>[...body.rows].filter(r=>!r.querySelector('td.empty,td[colspan]')),more=document.createElement('button');more.type='button';more.className='btn btn-sm st-table-more';
 const apply=()=>{const list=rowsOf();if(st.col>=0){list.sort((a,b)=>{const x=staffCellValue(a.cells[st.col]),y=staffCellValue(b.cells[st.col]);return(x.n&&y.n?x.v-y.v:String(x.v).localeCompare(String(y.v),'fa',{numeric:true}))*st.dir});list.forEach(r=>body.appendChild(r))}list.forEach((r,i)=>r.hidden=i>=st.limit);more.hidden=list.length<=st.limit;more.textContent=`نمایش بیشتر (${(list.length-st.limit).toLocaleString('fa-IR')} ردیف دیگر)`};
 more.onclick=()=>{st.limit+=STAFF_TABLE_PAGE;apply()};(t.closest('.table-wrap')||t).after(more);
 if(rowsOf().length>1)[...(t.tHead?.rows[0]?.cells||[])].forEach((th,i)=>{if(!S(th.textContent))return;th.classList.add('st-sortable');th.title='برای مرتب‌سازی کلیک کنید';th.onclick=()=>{st.dir=st.col===i?-st.dir:1;st.col=i;t.querySelectorAll('th[data-sort]').forEach(h=>h.removeAttribute('data-sort'));th.dataset.sort=st.dir>0?'asc':'desc';apply()}});
 apply()})}
const staffOldRender=render;render=function(){const out=document.getElementById('staffView');if(!out||!me)return;const map={dashboard:dashboardView,allShifts:()=>shiftView(false),myShifts:()=>shiftView(true),training:trainingView,checklists:checklistsView,leave:leaveView,payments:paymentsView,advance:advanceView,history:historyView,myTips:myTipsView,reservations:reservationsView,assetIncident:assetIncidentView,suppliers:staffSuppliersView,cash:cashView,request:requestView,invoice:invoiceView,tips:tipsView,survey:surveyView,inventoryEvent:staffInventoryEventView,inventoryTransfer:staffInventoryTransferView,inventoryCount:staffInventoryCountView,beverageControl:staffBeverageView};out.innerHTML=(map[view]||dashboardView)();document.getElementById('staffTitle').textContent=staffMenuItems().find(x=>x[0]===view)?.[2]||'پنل پرسنل';setTimeout(()=>{window.RayoJalali?.mark?.();staffSelectPlaceholders();staffEnhanceTables();if(view==='cash')staffCashStatCheck()},0)}

